result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/leaderboard.test.js", "content": "const test = require('node:test');
const assert = require('node:assert');
const { topScores } = require('./leaderboard.js');

test('returns top n scores in descending numeric order', () => {
  const input = [5, 100, 9, 22];
  assert.deepStrictEqual(topScores(input, 2), [100, 22]);
});

test('does not mutate the original input array', () => {
  const input = [5, 100, 9, 22];
  topScores(input, 2);
  assert.deepStrictEqual(input, [5, 100, 9, 22]);
});

test('handles ties (keeps both equal values)', () => {
  const input = [50, 50, 10, 99];
  assert.deepStrictEqual(topScores(input, 3), [99, 50, 50]);
});

test('handles negative scores', () => {
  const input = [-5, -100, 0, -1];
  assert.deepStrictEqual(topScores(input, 3), [0, -1, -5]);
});
"})
